public void postBuild()
{
    super();
    BDRJobContract bdrJobContract = this.dataContractObject() as BDRJobContract;
    DialogField dialogField = this.bindInfo().getDialogField(bdrJobContract, methodStr(BDRJobContract, parmEnvironmentId));
    dialogField.allowEdit(false);
